                 initial=None, help_text='', *args, **kwargs):
        self.path, self.match, self.recursive = path, match, recursive
        self.allow_files, self.allow_folders = allow_files, allow_folders
        super().__init__(**kwargs, required=required, widget=widget, label=label,
                         initial=initial, help_text=help_text, *args, **kwargs)

    def deep_copy(self, memo):
        result = super().deep_copy(memo)
        result.path = copy.deepcopy(self.path, memo)
        return result

    def to_python(self, value):
        return value

    def bound_data(self, data, initial):
        return initial

    def _set_choices(self, value):
        # Force choices into a list of tuples with string keys.
        value = [(str(k), str(v)) for k, v in value]
        super()._set_choices(value)

    choices = property(_get_choices, _set_choices)

    def _get_choices(self):
        if not hasattr(self, '_choices'):
            self._choices = self.widget.choices = self.choices_for_files()
        return self._choices

    def choices_for_files(self):
        # Get the file paths
        if not self.path:
            return []
        # Get the absolute path
        absolute_path = os.path.abspath(self.path)
        # Get the list of files
        file_list = os.listdir(absolute_path)
        # Sort the list
        file_list.sort()
        # Build the choices
        choices = []
        for f in file_list:
            if self.match is None or re_match(self.match, f):
                full_file_path = os.path.join(absolute_path, f)
                if self.allow_files and os.path.isfile(full_file_path):
                    choices.append((full_file_path, f))
                elif self.allow_folders and os.path.isdir(full_file_path):
                    choices.append((full_file_path, f))
        return choices
